const TW_MODULES=[{"t": "Mengenal Tailwind CSS", "lvl": "Pemula", "d": "Apa itu utility-first, cara memasang Tailwind, dan kelas dasar untuk jarak, warna, dan huruf.", "nodes": ["Utility-first", "Installation", "Spacing", "Colors", "Typography"], "lessons": [{"k": "w", "t": "Utility-first dan cara memasang", "nodes": [], "b": ["Tailwind CSS adalah framework <b>utility-first</b>: alih-alih menulis CSS sendiri, kamu menempelkan kelas kecil yang masing-masing melakukan satu hal, misalnya <code>p-4</code> (padding), <code>bg-sky-600</code> (warna latar), <code>rounded-lg</code> (sudut membulat).", "Untuk belajar dan mencoba cepat, cukup pasang <b>Play CDN</b>: <code>&lt;script src=\"https://cdn.tailwindcss.com\"&gt;&lt;/script&gt;</code>. Pratinjau di halaman ini memakai cara itu (Tailwind 3.4). Untuk proyek sungguhan, pasang lewat npm agar CSS yang dihasilkan kecil dan hanya berisi kelas yang dipakai.", "Cara pasang Tailwind v4 di proyek Vite: <code>npm install tailwindcss @tailwindcss/vite</code>, tambahkan plugin <code>tailwindcss()</code> di <code>vite.config.js</code>, lalu tulis <code>@import \"tailwindcss\";</code> di file CSS utama. Di v3 kamu memakai <code>tailwind.config.js</code> dan tiga baris <code>@tailwind base; @tailwind components; @tailwind utilities;</code>.", "Kelas di Tailwind v3 dan v4 hampir sama, jadi yang kamu pelajari di sini berlaku di keduanya."], "html": "<div class=\"max-w-sm mx-auto mt-6 p-6 bg-white rounded-xl shadow-md\">\n  <h1 class=\"text-2xl font-bold text-slate-800\">Toko Nusantara</h1>\n  <p class=\"mt-2 text-slate-600\">Kopi, teh, dan camilan pilihan.</p>\n  <button class=\"mt-4 px-4 py-2 bg-sky-600 text-white rounded-lg\">Belanja sekarang</button>\n</div>", "tw": true, "task": {"q": "Ubah tombol menjadi hijau: ganti <code>bg-sky-600</code> dengan <code>bg-emerald-600</code>.", "test": "document.querySelector('button').classList.contains('bg-emerald-600')", "hint": "Cukup ganti nama kelasnya di atribut class pada tombol."}, "pts": ["Utility-first: satu kelas, satu tugas gaya.", "Play CDN untuk mencoba; npm + Vite untuk proyek.", "v4: @import \"tailwindcss\"; v3: tailwind.config.js + @tailwind."], "q": [["Apa arti utility-first?", ["Menyusun tampilan dari banyak kelas kecil yang masing-masing satu tugas", "Menulis semua CSS di satu file besar", "Memakai komponen siap pakai saja"], 0, "Setiap kelas utilitas mengatur satu properti CSS."], ["Baris apa yang dipakai Tailwind v4 di file CSS?", ["@import \"tailwindcss\";", "@tailwind all;", "@use tailwind;"], 0, "v4 cukup satu baris import."]], "so": [{"q": "Buat kartu profil: lebar maksimal <code>max-w-xs</code>, padding 6, latar putih, sudut <code>rounded-2xl</code>, bayangan <code>shadow-lg</code>, berisi nama tebal dan peran berwarna abu-abu.", "h": "Gabungkan kelas di satu div, lalu kelas teks di h2 dan p.", "a": "<div class=\"max-w-xs p-6 bg-white rounded-2xl shadow-lg\">\n  <h2 class=\"text-xl font-bold text-slate-900\">Rina Siregar</h2>\n  <p class=\"text-slate-500\">Flutter Developer</p>\n</div>", "lang": "html"}, {"q": "Tulis isi file CSS utama dan potongan konfigurasi Vite untuk memasang Tailwind v4.", "h": "Plugin @tailwindcss/vite dan satu baris @import.", "a": "<!-- src/style.css -->\n@import \"tailwindcss\";\n\n<!-- vite.config.js -->\nimport { defineConfig } from 'vite'\nimport tailwindcss from '@tailwindcss/vite'\nexport default defineConfig({ plugins: [tailwindcss()] })", "lang": "html"}]}, {"k": "w", "t": "Jarak, ukuran, dan warna", "nodes": [], "b": ["Skala jarak Tailwind: angka 1 = 0.25rem (4px). Jadi <code>p-4</code> = padding 16px, <code>m-2</code> = margin 8px. Tambahkan arah: <code>px</code> (kiri-kanan), <code>py</code> (atas-bawah), <code>mt</code>, <code>mb</code>, <code>ml</code>, <code>mr</code>.", "Lebar dan tinggi: <code>w-64</code> (16rem), <code>w-full</code>, <code>w-1/2</code>, <code>h-12</code>, <code>max-w-md</code>.", "Warna mengikuti pola <code>{properti}-{warna}-{tingkat}</code>: <code>bg-rose-500</code>, <code>text-slate-700</code>, <code>border-amber-300</code>. Tingkat 50 paling terang sampai 950 paling gelap. Tambah transparansi dengan garis miring: <code>bg-sky-600/20</code>.", "Kalau butuh nilai khusus, pakai kurung siku (arbitrary value): <code>w-[310px]</code>, <code>bg-[#B4532A]</code>."], "html": "<div class=\"p-6 space-y-3\">\n  <div class=\"p-2 bg-amber-100 text-amber-900 rounded\">p-2</div>\n  <div class=\"p-4 bg-amber-200 text-amber-900 rounded\">p-4</div>\n  <div class=\"p-8 bg-amber-300 text-amber-900 rounded\">p-8</div>\n  <div class=\"w-1/2 py-2 px-4 bg-[#B4532A] text-white rounded\">w-1/2 dengan warna khusus</div>\n</div>", "tw": true, "task": {"q": "Beri kotak pertama padding <code>p-6</code> dan latar <code>bg-rose-200</code>.", "test": "(e=>e.classList.contains('p-6')&&e.classList.contains('bg-rose-200'))(document.querySelector('.space-y-3 > div'))", "hint": "Ganti p-2 menjadi p-6 dan bg-amber-100 menjadi bg-rose-200 di div pertama."}, "pts": ["1 unit = 0.25rem = 4px.", "Pola warna: bg-/text-/border- + nama + tingkat 50–950.", "Nilai khusus memakai [ ], misalnya w-[310px]."], "q": [["Berapa padding dari kelas p-4?", ["16px (1rem)", "4px", "40px"], 0, "4 × 0.25rem = 1rem = 16px."], ["Kelas mana yang memberi warna teks abu-abu gelap?", ["text-slate-700", "bg-slate-700", "font-slate-700"], 0, "Awalan text- mengatur warna teks."], ["Kelas bg-sky-600/20 berarti?", ["Warna sky-600 dengan opasitas 20%", "Lebar 20", "Padding 20"], 0, "Garis miring mengatur transparansi."]], "so": [{"q": "Buat tiga lencana status: \"Lunas\" hijau, \"Menunggu\" kuning, \"Batal\" merah, masing-masing <code>px-3 py-1 rounded-full text-sm</code> dengan latar tingkat 100 dan teks tingkat 800.", "h": "Pola bg-{warna}-100 text-{warna}-800.", "a": "<span class=\"px-3 py-1 rounded-full text-sm bg-emerald-100 text-emerald-800\">Lunas</span>\n<span class=\"px-3 py-1 rounded-full text-sm bg-amber-100 text-amber-800\">Menunggu</span>\n<span class=\"px-3 py-1 rounded-full text-sm bg-rose-100 text-rose-800\">Batal</span>", "lang": "html"}, {"q": "Buat kotak 120×120 piksel tepat berwarna #B4532A dengan nilai arbitrer.", "h": "w-[120px] h-[120px] bg-[#B4532A].", "a": "<div class=\"w-[120px] h-[120px] bg-[#B4532A] rounded-lg\"></div>", "lang": "html"}]}, {"k": "w", "t": "Tipografi", "nodes": [], "b": ["Ukuran huruf: <code>text-xs</code>, <code>text-sm</code>, <code>text-base</code>, <code>text-lg</code>, <code>text-xl</code> sampai <code>text-9xl</code>.", "Tebal huruf: <code>font-normal</code>, <code>font-medium</code>, <code>font-semibold</code>, <code>font-bold</code>. Keluarga huruf: <code>font-sans</code>, <code>font-serif</code>, <code>font-mono</code>.", "Lainnya: <code>leading-relaxed</code> (jarak baris), <code>tracking-wide</code> (jarak huruf), <code>uppercase</code>, <code>italic</code>, <code>underline</code>, <code>text-center</code>, <code>truncate</code> (potong dengan elipsis)."], "html": "<article class=\"p-6 max-w-prose\">\n  <p class=\"text-xs uppercase tracking-widest text-slate-500\">Resep</p>\n  <h1 class=\"text-3xl font-serif text-slate-900\">Kopi Tubruk</h1>\n  <p class=\"mt-3 text-base text-slate-700\">Seduh dua sendok kopi bubuk dengan air mendidih, aduk, lalu tunggu ampasnya turun.</p>\n</article>", "tw": true, "task": {"q": "Jadikan paragraf terakhir lebih lega: tambahkan kelas <code>leading-relaxed</code>.", "test": "document.querySelector('article p:last-child').classList.contains('leading-relaxed')", "hint": "Tambahkan leading-relaxed di atribut class paragraf terakhir."}, "pts": ["text-* untuk ukuran, font-* untuk tebal dan keluarga.", "leading-* jarak baris, tracking-* jarak huruf."], "q": [["Kelas apa untuk huruf tebal?", ["font-bold", "text-bold", "bold"], 0, "Ketebalan memakai awalan font-."]], "so": [{"q": "Buat kutipan: teks besar miring, garis kiri tebal berwarna, dan nama penulis kecil berhuruf kapital.", "h": "border-l-4 border-sky-500 pl-4 italic text-lg; uppercase tracking-wide text-xs untuk nama.", "a": "<blockquote class=\"border-l-4 border-sky-500 pl-4\">\n  <p class=\"text-lg italic text-slate-800\">\"Kode yang baik adalah kode yang mudah dibaca orang lain.\"</p>\n  <footer class=\"mt-2 text-xs uppercase tracking-wide text-slate-500\">Mentor Ruang Kode</footer>\n</blockquote>", "lang": "html"}, {"q": "Potong judul panjang menjadi satu baris berelipsis di dalam kotak selebar 200 px.", "h": "truncate memerlukan lebar terbatas.", "a": "<h3 class=\"w-[200px] truncate font-semibold\">Belajar Kotlin Multiplatform dari nol sampai rilis</h3>", "lang": "html"}]}]}, {"t": "Tata letak dan responsif", "lvl": "Menengah", "d": "Flexbox, grid, layar responsif, dan keadaan seperti hover, focus, serta mode gelap.", "nodes": ["Flexbox", "Grid", "Responsive Design", "Hover, Focus", "Dark Mode"], "lessons": [{"k": "w", "t": "Flexbox dan Grid", "nodes": [], "b": ["<code>flex</code> menjadikan elemen wadah flexbox. Atur arah dengan <code>flex-row</code>/<code>flex-col</code>, perataan dengan <code>justify-between</code>, <code>justify-center</code>, <code>items-center</code>, dan jarak antaranak dengan <code>gap-4</code>.", "<code>grid</code> plus <code>grid-cols-3</code> membuat tiga kolom sama lebar. <code>col-span-2</code> membuat satu anak memakan dua kolom.", "Pola umum navbar: <code>flex items-center justify-between</code>. Pola galeri kartu: <code>grid grid-cols-2 gap-4</code>."], "html": "<nav class=\"flex items-center justify-between p-4 bg-slate-800 text-white\">\n  <b>Ruang</b>\n  <div class=\"flex gap-4 text-sm\"><a>Beranda</a><a>Kursus</a><a>Masuk</a></div>\n</nav>\n<section id=\"galeri\" class=\"grid grid-cols-2 gap-4 p-4\">\n  <div class=\"p-4 bg-sky-100 rounded\">Dart</div>\n  <div class=\"p-4 bg-sky-100 rounded\">Kotlin</div>\n  <div class=\"p-4 bg-sky-100 rounded\">Flutter</div>\n  <div class=\"p-4 bg-sky-100 rounded\">Compose</div>\n</section>", "tw": true, "task": {"q": "Ubah galeri menjadi tiga kolom dengan <code>grid-cols-3</code>.", "test": "document.getElementById('galeri').classList.contains('grid-cols-3')", "hint": "Ganti grid-cols-2 menjadi grid-cols-3 pada section#galeri."}, "pts": ["flex + justify-* + items-* + gap-*.", "grid + grid-cols-N + col-span-N."], "q": [["Kelas mana yang menaruh anak flex di tengah secara vertikal?", ["items-center", "justify-center", "align-middle"], 0, "items-* mengatur sumbu silang (vertikal pada flex-row)."], ["Kelas untuk jarak antaranak flex atau grid?", ["gap-4", "space-4", "margin-4"], 0, "gap bekerja di flex dan grid."]], "so": [{"q": "Buat footer tiga kolom yang ditumpuk di ponsel dan berjajar mulai md, dengan jarak 6.", "h": "flex flex-col md:flex-row gap-6, atau grid grid-cols-1 md:grid-cols-3.", "a": "<footer class=\"grid grid-cols-1 md:grid-cols-3 gap-6 p-6 bg-slate-900 text-slate-300\">\n  <div><b class=\"text-white\">RuangKode</b><p class=\"text-sm\">Belajar coding berbahasa Indonesia.</p></div>\n  <div><b class=\"text-white\">Jalur</b><p class=\"text-sm\">Dart, Kotlin, Tailwind</p></div>\n  <div><b class=\"text-white\">Kontak</b><p class=\"text-sm\">halo@ruangkode.id</p></div>\n</footer>", "lang": "html"}, {"q": "Buat tata letak dasbor: sidebar selebar 1 kolom dan konten 3 kolom dalam grid 4 kolom.", "h": "grid grid-cols-4, lalu col-span-3 pada konten.", "a": "<div class=\"grid grid-cols-4 gap-4 p-4 min-h-[200px]\">\n  <aside class=\"col-span-1 bg-slate-100 rounded p-3\">Menu</aside>\n  <main class=\"col-span-3 bg-white border rounded p-3\">Konten</main>\n</div>", "lang": "html"}]}, {"k": "w", "t": "Desain responsif", "nodes": [], "b": ["Tailwind <b>mobile-first</b>: kelas tanpa awalan berlaku di semua ukuran, kelas berawalan berlaku mulai lebar tertentu ke atas.", "Titik henti bawaan: <code>sm</code> 640px, <code>md</code> 768px, <code>lg</code> 1024px, <code>xl</code> 1280px, <code>2xl</code> 1536px.", "Contoh: <code>grid-cols-1 md:grid-cols-3</code> berarti satu kolom di ponsel dan tiga kolom mulai 768px. <code>hidden md:block</code> menyembunyikan elemen di layar kecil.", "Ubah lebar jendela pratinjau (atau buka di ponsel) untuk melihat perbedaannya."], "html": "<div id=\"kartu\" class=\"grid grid-cols-1 gap-3 p-4\">\n  <div class=\"p-4 bg-emerald-100 rounded\">Satu</div>\n  <div class=\"p-4 bg-emerald-100 rounded\">Dua</div>\n  <div class=\"p-4 bg-emerald-100 rounded\">Tiga</div>\n</div>\n<p class=\"px-4 text-sm text-slate-500\"><span class=\"sm:hidden\">Layar kecil</span><span class=\"hidden sm:inline\">Layar sm ke atas</span></p>", "tw": true, "task": {"q": "Buat kartu tampil tiga kolom mulai layar <code>md</code>: tambahkan <code>md:grid-cols-3</code>.", "test": "document.getElementById('kartu').classList.contains('md:grid-cols-3')", "hint": "Tambahkan md:grid-cols-3 di atribut class div#kartu."}, "pts": ["Mobile-first: kelas polos untuk ponsel, awalan untuk layar lebih besar.", "sm 640, md 768, lg 1024, xl 1280, 2xl 1536."], "q": [["Kelas md:text-lg berlaku kapan?", ["Mulai lebar 768px ke atas", "Hanya di bawah 768px", "Hanya tepat 768px"], 0, "Awalan berarti \"mulai dari ukuran ini ke atas\"."]], "so": [{"q": "Buat judul yang berukuran <code>text-2xl</code> di ponsel, <code>text-4xl</code> mulai md, dan <code>text-6xl</code> mulai lg.", "h": "Tumpuk kelas dengan awalan berbeda.", "a": "<h1 class=\"text-2xl md:text-4xl lg:text-6xl font-extrabold\">Belajar Flutter</h1>", "lang": "html"}, {"q": "Tampilkan menu navigasi hanya mulai md, dan tombol hamburger hanya di ponsel.", "h": "hidden md:flex untuk menu; md:hidden untuk tombol.", "a": "<nav class=\"flex items-center justify-between p-4\">\n  <b>RuangKode</b>\n  <div class=\"hidden md:flex gap-4\"><a>Beranda</a><a>Kursus</a></div>\n  <button class=\"md:hidden\" aria-label=\"Buka menu\">☰</button>\n</nav>", "lang": "html"}]}, {"k": "w", "t": "Hover, focus, dan mode gelap", "nodes": [], "b": ["Awalan keadaan (variant) menerapkan kelas hanya saat kondisi tertentu: <code>hover:bg-sky-700</code>, <code>focus:ring-2</code>, <code>active:scale-95</code>, <code>disabled:opacity-50</code>.", "<code>group</code> dan <code>group-hover:</code> mengubah anak saat induknya di-hover. <code>peer</code> dan <code>peer-checked:</code> mengubah elemen saudara.", "Mode gelap: <code>dark:bg-slate-900</code>. Secara bawaan mengikuti pengaturan sistem; di v3 kamu bisa memakai strategi kelas (<code>darkMode: 'class'</code>) agar bisa diganti lewat tombol.", "Tambahkan <code>transition</code> dan <code>duration-200</code> agar perubahan terlihat halus."], "html": "<div class=\"p-6 space-y-4\">\n  <button id=\"beli\" class=\"px-4 py-2 bg-sky-600 text-white rounded-lg transition duration-200\">Arahkan kursor ke saya</button>\n  <input class=\"block w-full border border-slate-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-sky-400\" placeholder=\"Klik untuk fokus\">\n  <a class=\"group block p-4 border rounded-lg hover:border-sky-500\">\n    <b class=\"group-hover:text-sky-600\">Kursus Flutter</b>\n    <p class=\"text-sm text-slate-500\">Arahkan kursor ke kartu ini.</p>\n  </a>\n</div>", "tw": true, "task": {"q": "Buat tombol menggelap saat di-hover dengan <code>hover:bg-sky-800</code>.", "test": "document.getElementById('beli').classList.contains('hover:bg-sky-800')", "hint": "Tambahkan hover:bg-sky-800 pada tombol#beli."}, "pts": ["Variant: hover:, focus:, active:, disabled:, dark:.", "group/group-hover: dan peer/peer-checked: untuk relasi elemen."], "q": [["Awalan mana untuk mode gelap?", ["dark:", "night:", "theme-dark:"], 0, "Tailwind memakai variant dark:."], ["Awalan untuk mengubah anak saat induknya di-hover?", ["peer-hover:", "group-hover:", "child-hover:"], 1, "Induk diberi kelas group."]], "so": [{"q": "Buat kartu yang sedikit membesar dan bayangannya menebal saat di-hover, dengan transisi halus.", "h": "transition duration-200 hover:scale-105 hover:shadow-xl.", "a": "<div class=\"p-6 bg-white rounded-xl shadow transition duration-200 hover:scale-105 hover:shadow-xl\">Kursus Kotlin</div>", "lang": "html"}, {"q": "Buat kotak centang yang membuat teks di sebelahnya tercoret saat dicentang, tanpa JavaScript.", "h": "Beri input kelas peer, lalu span dengan peer-checked:line-through.", "a": "<label class=\"flex items-center gap-2\">\n  <input type=\"checkbox\" class=\"peer\">\n  <span class=\"peer-checked:line-through peer-checked:text-slate-400\">Belajar Tailwind</span>\n</label>", "lang": "html"}, {"q": "Buat kartu yang berwarna terang dan otomatis gelap di mode gelap.", "h": "bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100.", "a": "<div class=\"p-6 rounded-xl bg-white text-slate-900 dark:bg-slate-800 dark:text-slate-100\">Mode gelap mengikuti sistem</div>", "lang": "html"}]}]}, {"t": "Komponen, kustomisasi, dan proyek", "lvl": "Menengah", "d": "Form, menyatukan kelas dengan @apply, mengatur tema sendiri, dan membuat landing page.", "nodes": ["Forms", "@apply", "Theme", "Configuration", "Project"], "lessons": [{"k": "w", "t": "Form yang rapi", "nodes": [], "b": ["Form dibangun dari utilitas biasa: <code>block</code>, <code>w-full</code>, <code>border</code>, <code>rounded-lg</code>, <code>px-3 py-2</code>, dan <code>focus:ring</code>.", "Untuk keadaan tidak valid, pakai variant <code>invalid:border-rose-500</code>. Plugin resmi <code>@tailwindcss/forms</code> menyamakan gaya bawaan input di semua browser.", "Tetap pakai <code>&lt;label&gt;</code> yang terhubung ke input lewat <code>for</code>/<code>id</code> agar mudah diakses."], "html": "<form class=\"max-w-sm p-6 space-y-4\">\n  <div>\n    <label for=\"email\" class=\"block text-sm font-medium text-slate-700\">Email</label>\n    <input id=\"email\" type=\"email\" required class=\"mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-sky-400 outline-none\">\n  </div>\n  <div>\n    <label for=\"sandi\" class=\"block text-sm font-medium text-slate-700\">Kata sandi</label>\n    <input id=\"sandi\" type=\"password\" class=\"mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2\">\n  </div>\n  <button class=\"w-full py-2 bg-sky-600 text-white rounded-lg\">Masuk</button>\n</form>", "tw": true, "task": {"q": "Samakan input kata sandi dengan input email: tambahkan <code>focus:ring-2</code> dan <code>focus:ring-sky-400</code>.", "test": "(e=>e.classList.contains('focus:ring-2')&&e.classList.contains('focus:ring-sky-400'))(document.getElementById('sandi'))", "hint": "Salin kelas focus:ring-2 focus:ring-sky-400 dari input email ke input#sandi."}, "pts": ["Form = utilitas biasa + focus:ring.", "invalid: untuk validasi visual; @tailwindcss/forms untuk gaya dasar input."], "q": [["Kenapa label tetap penting walau ada placeholder?", ["Pembaca layar dan klik label membutuhkannya", "Supaya Tailwind bekerja", "Tidak penting"], 0, "Label adalah nama aksesibel input."]], "so": [{"q": "Tambahkan pesan error merah di bawah input email yang hanya terlihat jika input tidak valid dan sudah diisi.", "h": "Kelas peer pada input, lalu p dengan hidden peer-[&:not(:placeholder-shown):invalid]:block. Bentuk lebih sederhana: invalid:border-rose-500 pada input.", "a": "<input type=\"email\" placeholder=\" \" class=\"peer block w-full border rounded-lg px-3 py-2 invalid:[&:not(:placeholder-shown)]:border-rose-500\">\n<p class=\"hidden mt-1 text-sm text-rose-600 peer-[&:not(:placeholder-shown):invalid]:block\">Format email belum benar.</p>", "lang": "html"}, {"q": "Buat select dan textarea yang gayanya seragam dengan input lain.", "h": "Pakai kelas yang sama: block w-full border rounded-lg px-3 py-2.", "a": "<select class=\"block w-full border border-slate-300 rounded-lg px-3 py-2\">\n  <option>Flutter</option><option>Compose</option>\n</select>\n<textarea rows=\"3\" class=\"mt-3 block w-full border border-slate-300 rounded-lg px-3 py-2\" placeholder=\"Catatan\"></textarea>", "lang": "html"}]}, {"k": "w", "t": "Komponen dan @apply", "nodes": [], "b": ["Kelas yang panjang dan berulang bisa disatukan. Cara yang disarankan: buat <b>komponen</b> di framework kamu (React, Vue, Blade) agar kelas ditulis sekali.", "Alternatifnya, <code>@apply</code> di file CSS: <code>.btn { @apply px-4 py-2 rounded-lg bg-sky-600 text-white; }</code>. Di Play CDN, tulis di dalam <code>&lt;style type=\"text/tailwindcss\"&gt;</code>.", "Gunakan @apply secukupnya. Kalau semuanya dipindah ke CSS, kamu kehilangan manfaat utama Tailwind: gaya terlihat langsung di HTML."], "html": "<style type=\"text/tailwindcss\">\n  .btn { @apply px-4 py-2 rounded-lg font-medium text-white; }\n  .btn-utama { @apply bg-sky-600 hover:bg-sky-700; }\n</style>\n<div class=\"p-6 flex gap-3\">\n  <button class=\"btn btn-utama\">Simpan</button>\n  <button class=\"btn btn-utama\">Kirim</button>\n  <button id=\"hapus\" class=\"btn bg-slate-500\">Hapus</button>\n</div>", "tw": true, "task": {"q": "Tambahkan kelas komponen <code>.btn-bahaya</code> berisi <code>@apply bg-rose-600;</code>, lalu pakai di tombol Hapus menggantikan <code>bg-slate-500</code>.", "test": "document.getElementById('hapus').classList.contains('btn-bahaya')&&/btn-bahaya/.test(document.querySelector('style[type=\"text/tailwindcss\"]').textContent)", "hint": "Tulis .btn-bahaya { @apply bg-rose-600; } di dalam style, lalu ganti bg-slate-500 dengan btn-bahaya."}, "pts": ["Utamakan komponen di framework.", "@apply menyatukan utilitas menjadi satu kelas CSS."], "q": [["Di Play CDN, @apply ditulis di mana?", ["&lt;style type=\"text/tailwindcss\">", "&lt;script>", "Atribut class"], 0, "Play CDN hanya memproses style dengan type text/tailwindcss."], ["Kekurangan memakai @apply berlebihan?", ["Gaya tidak lagi terlihat langsung di HTML", "Tidak bisa responsif", "Membuat error"], 0, "Manfaat utama utility-first hilang."]], "so": [{"q": "Buat kelas komponen <code>.kartu</code> dengan @apply (padding 6, latar putih, sudut xl, bayangan) dan pakai di dua kartu.", "h": "Tulis di &lt;style type=\"text/tailwindcss\">.", "a": "<style type=\"text/tailwindcss\">\n  .kartu { @apply p-6 bg-white rounded-xl shadow; }\n</style>\n<div class=\"kartu\">Dart</div>\n<div class=\"kartu mt-4\">Kotlin</div>", "lang": "html"}]}, {"k": "w", "t": "Tema dan konfigurasi", "nodes": [], "b": ["Warna merek, font, dan jarak sendiri didaftarkan di tema. Di <b>v3</b> lewat <code>tailwind.config.js</code> bagian <code>theme.extend</code>. Di Play CDN, isi <code>tailwind.config = {...}</code> di skrip.", "Di <b>v4</b>, tema ditulis di CSS: <code>@theme { --color-merek: #B4532A; --font-judul: \"Fraunces\", serif; }</code>. Setelah itu kelas <code>bg-merek</code> dan <code>font-judul</code> langsung tersedia.", "Contoh di bawah mendaftarkan warna <code>merek</code> lewat skrip konfigurasi."], "html": "<script>\n  tailwind.config = { theme: { extend: { colors: { merek: '#B4532A', krem: '#FBF3E4' } } } }\n</script>\n<div class=\"p-6 bg-krem\">\n  <h1 class=\"text-2xl font-bold text-merek\">Kedai Kopi Senja</h1>\n  <button id=\"pesan\" class=\"mt-3 px-4 py-2 text-white rounded-lg bg-slate-700\">Pesan</button>\n</div>", "tw": true, "task": {"q": "Pakai warna tema: ganti <code>bg-slate-700</code> pada tombol dengan <code>bg-merek</code>.", "test": "document.getElementById('pesan').classList.contains('bg-merek')", "hint": "Kelas bg-merek tersedia karena merek didaftarkan di theme.extend.colors."}, "pts": ["v3: theme.extend di tailwind.config.js.", "v4: @theme { --color-*: ... } di CSS."], "q": [["Setelah --color-merek didaftarkan di @theme (v4), kelas apa yang muncul?", ["bg-merek, text-merek, border-merek, dll.", "Hanya .merek", "Tidak ada"], 0, "Tailwind membuat semua utilitas warna dari token itu."]], "so": [{"q": "Daftarkan font \"Fraunces\" sebagai <code>font-judul</code> dan jarak khusus <code>18</code> = 4.5rem lewat konfigurasi Play CDN.", "h": "theme.extend.fontFamily dan theme.extend.spacing.", "a": "<script>\n  tailwind.config = { theme: { extend: {\n    fontFamily: { judul: ['Fraunces', 'serif'] },\n    spacing: { 18: '4.5rem' }\n  } } }\n</script>\n<h1 class=\"font-judul text-3xl mt-18\">Kedai Kopi Senja</h1>", "lang": "html"}, {"q": "Tulis versi Tailwind v4 dari konfigurasi warna merek #B4532A dan krem #FBF3E4.", "h": "Di v4, tema ditulis di CSS dengan @theme dan variabel --color-*.", "a": "@import \"tailwindcss\";\n\n@theme {\n  --color-merek: #B4532A;\n  --color-krem: #FBF3E4;\n}", "lang": "html"}]}, {"k": "w", "t": "Proyek: landing page responsif", "nodes": [], "b": ["Saatnya menggabungkan semuanya: navbar flex, hero dengan tipografi besar, grid fitur yang responsif, dan tombol dengan hover.", "Perhatikan pola mobile-first: grid satu kolom di ponsel, tiga kolom mulai <code>md</code>.", "Tantangan: tambahkan satu kartu fitur keempat dan buat grid menjadi empat kolom di layar <code>lg</code>."], "html": "<header class=\"flex items-center justify-between px-6 py-4 border-b\">\n  <b class=\"text-lg\">Ruang<span class=\"text-sky-600\">Kode</span></b>\n  <a class=\"px-3 py-1.5 text-sm bg-sky-600 hover:bg-sky-700 text-white rounded-lg\">Daftar</a>\n</header>\n<main class=\"px-6 py-10 text-center\">\n  <h1 class=\"text-3xl md:text-5xl font-extrabold tracking-tight\">Belajar coding, langkah demi langkah</h1>\n  <p class=\"mt-3 text-slate-600 max-w-xl mx-auto\">Dari Dart sampai Kotlin, langsung praktik di browser.</p>\n</main>\n<section id=\"fitur\" class=\"grid grid-cols-1 md:grid-cols-3 gap-4 px-6 pb-10\">\n  <div class=\"p-5 rounded-xl bg-slate-50 border\"><b>Editor langsung</b><p class=\"text-sm text-slate-600\">Tulis kode, lihat hasilnya.</p></div>\n  <div class=\"p-5 rounded-xl bg-slate-50 border\"><b>Kuis</b><p class=\"text-sm text-slate-600\">Uji pemahaman tiap pelajaran.</p></div>\n  <div class=\"p-5 rounded-xl bg-slate-50 border\"><b>Peta belajar</b><p class=\"text-sm text-slate-600\">Ikuti urutan yang jelas.</p></div>\n</section>", "tw": true, "task": {"q": "Tambahkan kartu fitur keempat di <code>#fitur</code> dan beri grid kelas <code>lg:grid-cols-4</code>.", "test": "(g=>g.children.length>=4&&g.classList.contains('lg:grid-cols-4'))(document.getElementById('fitur'))", "hint": "Salin satu div kartu, ubah isinya, lalu tambahkan lg:grid-cols-4 pada section#fitur."}, "pts": ["Gabungkan flex, grid, tipografi, dan variant.", "Mulai dari ponsel, lalu tambah awalan md:/lg:."], "q": [["Urutan kelas mana yang benar untuk 1 kolom di ponsel dan 3 kolom di tablet?", ["grid-cols-1 md:grid-cols-3", "md:grid-cols-1 grid-cols-3", "grid-cols-3 sm:grid-cols-1"], 0, "Kelas polos untuk layar kecil, awalan untuk layar besar."]], "so": [{"q": "Tambahkan bagian testimoni dua kolom (satu kolom di ponsel) dengan foto bulat, nama, dan kutipan.", "h": "grid md:grid-cols-2 gap-4; foto memakai w-12 h-12 rounded-full.", "a": "<section class=\"grid md:grid-cols-2 gap-4 px-6 pb-10\">\n  <figure class=\"p-5 border rounded-xl\">\n    <div class=\"flex items-center gap-3\">\n      <div class=\"w-12 h-12 rounded-full bg-sky-200\"></div>\n      <figcaption><b>Rina</b><p class=\"text-sm text-slate-500\">Mahasiswa</p></figcaption>\n    </div>\n    <blockquote class=\"mt-3 text-slate-700\">\"Materinya runtut dan ada latihannya.\"</blockquote>\n  </figure>\n  <figure class=\"p-5 border rounded-xl\">\n    <div class=\"flex items-center gap-3\">\n      <div class=\"w-12 h-12 rounded-full bg-emerald-200\"></div>\n      <figcaption><b>Budi</b><p class=\"text-sm text-slate-500\">Guru SMK</p></figcaption>\n    </div>\n    <blockquote class=\"mt-3 text-slate-700\">\"Cocok untuk kelas praktik.\"</blockquote>\n  </figure>\n</section>", "lang": "html"}]}]}, {"t": "Efek, posisi, dan interaksi", "lvl": "Menengah", "d": "Posisi dan lapisan, transformasi dan animasi, menu interaktif dengan sedikit JavaScript, dan apa yang baru di Tailwind v4.", "nodes": ["Position", "Transforms", "Animation", "Tailwind v4"], "lessons": [{"k": "w", "t": "Posisi, z-index, dan overflow", "nodes": [], "b": ["<code>relative</code> menjadikan elemen patokan, lalu anak <code>absolute</code> diletakkan dengan <code>top-2</code>, <code>right-2</code>, <code>inset-0</code>. <code>fixed</code> menempel di layar, dan <code>sticky top-0</code> menempel saat digulir.", "Lapisan diatur dengan <code>z-10</code>, <code>z-20</code>, sampai <code>z-50</code>. Konten yang meluber diatur dengan <code>overflow-hidden</code>, <code>overflow-auto</code>, atau <code>overflow-x-auto</code> (untuk tabel lebar).", "Pola umum: lencana di pojok gambar, header lengket, dan lapisan gelap di atas gambar hero."], "html": "<header class=\"sticky top-0 z-10 bg-white/90 backdrop-blur border-b px-4 py-3 font-bold\">Header lengket</header>\n<div class=\"p-4 space-y-4\">\n  <div id=\"foto\" class=\"w-56 h-36 rounded-xl bg-gradient-to-br from-amber-300 to-rose-400\">\n    <span id=\"lencana\" class=\"px-2 py-1 text-xs font-bold text-white bg-rose-600 rounded\">Baru</span>\n  </div>\n  <p class=\"text-slate-600\">Gulir ke bawah untuk melihat header tetap di atas.</p>\n  <div class=\"h-64\"></div>\n</div>", "tw": true, "task": {"q": "Taruh lencana di pojok kanan atas foto: beri <code>#foto</code> kelas <code>relative</code> dan lencana kelas <code>absolute top-2 right-2</code>.", "test": "(f=>f.classList.contains('relative'))(document.getElementById('foto'))&&(l=>['absolute','top-2','right-2'].every(c=>l.classList.contains(c)))(document.getElementById('lencana'))", "hint": "Induk relative menjadi patokan posisi anak absolute."}, "pts": ["relative + absolute untuk posisi di dalam elemen.", "sticky top-0 untuk header lengket.", "z-* untuk urutan lapisan."], "q": [["Agar anak absolute diposisikan terhadap induknya, induk diberi kelas?", ["relative", "static", "block"], 0, "Tanpa relative, patokannya elemen lain di atasnya."]]}, {"k": "w", "t": "Transform, transisi, dan animasi", "nodes": [], "b": ["Transformasi: <code>scale-105</code>, <code>rotate-6</code>, <code>-translate-y-1</code>. Gabungkan dengan variant: <code>hover:-translate-y-1</code> membuat kartu terangkat saat di-hover.", "Transisi: <code>transition</code> (warna, opasitas, transform), <code>duration-300</code>, dan <code>ease-out</code>. Tanpa kelas transition, perubahan terjadi seketika.", "Animasi bawaan: <code>animate-spin</code> (ikon memuat), <code>animate-pulse</code> (skeleton loading), <code>animate-bounce</code>, <code>animate-ping</code>. Hormati pengguna yang memilih mengurangi animasi dengan <code>motion-reduce:animate-none</code>."], "html": "<div class=\"p-6 space-y-6\">\n  <div id=\"kartu\" class=\"w-60 p-5 bg-white border rounded-xl shadow-sm\">Arahkan kursor ke kartu ini</div>\n  <div class=\"flex items-center gap-3\">\n    <div class=\"w-6 h-6 border-4 border-sky-500 border-t-transparent rounded-full animate-spin motion-reduce:animate-none\"></div>\n    <span>Memuat data...</span>\n  </div>\n  <div class=\"w-60 space-y-2 animate-pulse\">\n    <div class=\"h-4 bg-slate-200 rounded\"></div>\n    <div class=\"h-4 w-2/3 bg-slate-200 rounded\"></div>\n  </div>\n</div>", "tw": true, "task": {"q": "Buat kartu terangkat saat di-hover: tambahkan <code>transition</code>, <code>hover:-translate-y-1</code>, dan <code>hover:shadow-lg</code>.", "test": "(k=>['transition','hover:-translate-y-1','hover:shadow-lg'].every(c=>k.classList.contains(c)))(document.getElementById('kartu'))", "hint": "Tiga kelas itu ditambahkan pada div#kartu."}, "pts": ["scale, rotate, translate untuk transformasi.", "transition + duration agar halus.", "animate-spin, animate-pulse; motion-reduce untuk aksesibilitas."], "q": [["Animasi yang cocok untuk skeleton loading?", ["animate-pulse", "animate-bounce", "animate-spin"], 0, "Denyut halus menandakan konten sedang dimuat."]]}, {"k": "w", "t": "Menu ponsel dengan sedikit JavaScript", "nodes": [], "b": ["Tailwind hanya mengurus tampilan. Untuk interaksi seperti membuka menu, cukup JavaScript kecil yang menambah atau membuang kelas: <code>menu.classList.toggle('hidden')</code>.", "Jangan lupa aksesibilitas: perbarui <code>aria-expanded</code> pada tombol agar pembaca layar tahu menu sedang terbuka atau tertutup.", "Di proyek React atau Vue, kelas ditentukan dari state, misalnya <code>className={buka ? 'block' : 'hidden'}</code>."], "html": "<nav class=\"bg-slate-900 text-white\">\n  <div class=\"flex items-center justify-between p-4\">\n    <b>RuangKode</b>\n    <button id=\"tombol\" class=\"px-3 py-1 border border-white/40 rounded\" aria-expanded=\"false\" aria-controls=\"menu\">Menu</button>\n  </div>\n  <div id=\"menu\" class=\"hidden flex-col gap-2 px-4 pb-4\">\n    <a class=\"block\">Beranda</a><a class=\"block\">Kursus</a><a class=\"block\">Masuk</a>\n  </div>\n</nav>", "js": "const tombol = document.getElementById('tombol');\nconst menu = document.getElementById('menu');\ntombol.addEventListener('click', () => {\n  // tulis kodemu di sini: tampilkan/sembunyikan menu\n});", "tw": true, "task": {"q": "Lengkapi JavaScript: saat tombol diklik, toggle kelas <code>hidden</code> pada menu dan perbarui <code>aria-expanded</code>. Klik tombolnya sekali lalu tekan Periksa.", "test": "(m=>!m.classList.contains('hidden'))(document.getElementById('menu'))&&document.getElementById('tombol').getAttribute('aria-expanded')==='true'", "hint": "const buka = menu.classList.toggle('hidden') === false; tombol.setAttribute('aria-expanded', buka);"}, "pts": ["Tailwind untuk gaya, JS kecil untuk interaksi.", "classList.toggle('hidden').", "Perbarui aria-expanded."], "q": [["classList.toggle('hidden') mengembalikan true jika?", ["Kelas baru saja ditambahkan", "Kelas dihapus", "Selalu true"], 0, "true = kelas sekarang ada."]]}, {"k": "c", "t": "Tailwind v4: apa yang baru dan cara migrasi", "nodes": [], "b": ["Tailwind v4 (rilis 2025) ditulis ulang agar jauh lebih cepat. Perubahan terbesar: konfigurasi pindah dari <code>tailwind.config.js</code> ke CSS. Kamu cukup menulis <code>@import \"tailwindcss\";</code> dan mengatur tema dengan <code>@theme</code>.", "Deteksi file otomatis (tidak perlu lagi mengisi <code>content</code>), warna bawaan memakai ruang warna OKLCH yang lebih cerah, dan fitur CSS modern seperti container query (<code>@container</code> dan <code>@md:</code>) sudah bawaan.", "Beberapa nama kelas berubah, misalnya <code>shadow-sm</code> menjadi <code>shadow-xs</code> dan <code>rounded</code> sekarang setara <code>rounded-sm</code> lama. Jalankan <code>npx @tailwindcss/upgrade</code> untuk memigrasi proyek v3 secara otomatis, lalu periksa hasilnya."], "lang": "css", "code": "/* v3: tailwind.config.js */\n/* module.exports = {\n     content: [\"./src/**/*.{html,js}\"],\n     theme: { extend: { colors: { merek: \"#B4532A\" } } }\n   } */\n\n/* v4: semuanya di CSS */\n@import \"tailwindcss\";\n\n@theme {\n  --color-merek: #B4532A;\n  --font-judul: \"Fraunces\", serif;\n  --breakpoint-3xl: 1920px;\n}\n\n/* kelas buatan sendiri */\n@utility tengah {\n  display: grid;\n  place-items: center;\n}", "tb": [{"c": "Tailwind v3 dibanding v4", "h": ["Hal", "v3", "v4"], "r": [["Konfigurasi", "tailwind.config.js", "@theme di CSS"], ["Memuat", "@tailwind base/components/utilities", "@import \"tailwindcss\""], ["Daftar file", "content: [...] wajib", "Otomatis"], ["Plugin Vite", "postcss + autoprefixer", "@tailwindcss/vite"], ["Kelas khusus", "@layer components", "@utility"], ["Container query", "Plugin terpisah", "Bawaan (@container, @md:)"]]}], "so": [{"q": "Tambahkan titik henti khusus <code>3xl</code> = 1920px dan warna <code>aksen</code> di Tailwind v4.", "h": "Variabel --breakpoint-* dan --color-* di dalam @theme.", "a": "@import \"tailwindcss\";\n\n@theme {\n  --breakpoint-3xl: 1920px;\n  --color-aksen: #0F5F8A;\n}", "lang": "css"}, {"q": "Buat kartu yang berubah menjadi dua kolom saat wadahnya (bukan layar) selebar md, memakai container query v4.", "h": "Induk diberi kelas @container, anak memakai @md:grid-cols-2.", "a": "<div class=\"@container\">\n  <div class=\"grid grid-cols-1 @md:grid-cols-2 gap-4\">\n    <img src=\"kopi.jpg\" alt=\"Kopi Gayo\" class=\"rounded-lg\">\n    <p>Kopi Gayo dari dataran tinggi Aceh.</p>\n  </div>\n</div>", "lang": "html"}], "pts": ["v4: @import \"tailwindcss\" dan @theme.", "Deteksi file otomatis, container query bawaan.", "npx @tailwindcss/upgrade untuk migrasi."], "q": [["Di v4, warna merek didaftarkan di mana?", ["tailwind.config.js", "Blok @theme di CSS", "package.json"], 1, "Konfigurasi berbasis CSS."]]}]}];
const BS_MODULES=[{"t": "Mengenal Bootstrap 5", "lvl": "Pemula", "d": "Cara memasang Bootstrap, sistem grid 12 kolom, dan kelas utilitas.", "nodes": ["Installation", "Grid System", "Utilities", "Typography", "Colors"], "lessons": [{"k": "w", "t": "Memasang Bootstrap 5", "nodes": [], "b": ["Bootstrap adalah framework CSS dengan <b>komponen siap pakai</b> (tombol, kartu, navbar, modal) dan sistem grid. Versi 5 tidak lagi membutuhkan jQuery.", "Cara cepat: tambahkan CSS di <code>&lt;head&gt;</code> dan bundle JS di akhir <code>&lt;body&gt;</code> dari CDN jsDelivr: <code>bootstrap@5.3.3/dist/css/bootstrap.min.css</code> dan <code>bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js</code>. Bundle sudah berisi Popper untuk dropdown dan tooltip.", "Lewat npm: <code>npm install bootstrap</code>, lalu <code>import \"bootstrap/dist/css/bootstrap.min.css\"</code> dan <code>import \"bootstrap\"</code> di file JS utama.", "Pratinjau di halaman ini sudah memuat Bootstrap 5.3, jadi kamu cukup menulis HTML."], "html": "<div class=\"container py-4\">\n  <h1 class=\"display-6\">Toko Nusantara</h1>\n  <p class=\"lead\">Kopi, teh, dan camilan pilihan.</p>\n  <button class=\"btn btn-primary\">Belanja sekarang</button>\n</div>", "bs": true, "task": {"q": "Ubah tombol menjadi hijau dengan mengganti <code>btn-primary</code> menjadi <code>btn-success</code>.", "test": "document.querySelector('.btn').classList.contains('btn-success')", "hint": "Ganti nama kelas btn-primary menjadi btn-success."}, "pts": ["Bootstrap 5 = komponen + grid + utilitas, tanpa jQuery.", "CSS di head, bootstrap.bundle.min.js di akhir body."], "q": [["Apa isi bootstrap.bundle.min.js selain JS Bootstrap?", ["Popper", "jQuery", "React"], 0, "Popper dibutuhkan dropdown, tooltip, dan popover."], ["Apakah Bootstrap 5 memerlukan jQuery?", ["Tidak", "Ya", "Hanya untuk grid"], 0, "Sejak v5 Bootstrap memakai JavaScript biasa."]], "so": [{"q": "Tulis kerangka HTML lengkap yang memuat Bootstrap 5.3.3 dari CDN jsDelivr.", "h": "link CSS di head, script bundle sebelum &lt;/body>, dan meta viewport.", "a": "<!doctype html>\n<html lang=\"id\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Toko</title>\n  <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n</head>\n<body>\n  <h1 class=\"container\">Halo, Bootstrap!</h1>\n  <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js\"></script>\n</body>\n</html>", "lang": "html"}, {"q": "Buat tiga tombol berdampingan: Simpan (primary), Batal (outline-secondary), Hapus (danger, kecil).", "h": "btn btn-primary, btn btn-outline-secondary, btn btn-danger btn-sm.", "a": "<div class=\"d-flex gap-2\">\n  <button class=\"btn btn-primary\">Simpan</button>\n  <button class=\"btn btn-outline-secondary\">Batal</button>\n  <button class=\"btn btn-danger btn-sm\">Hapus</button>\n</div>", "lang": "html"}]}, {"k": "w", "t": "Sistem grid 12 kolom", "nodes": [], "b": ["Grid Bootstrap terdiri dari <code>.container</code> → <code>.row</code> → <code>.col</code>. Setiap baris dibagi 12 kolom.", "<code>col-4</code> mengambil 4 dari 12 kolom (sepertiga). Tambahkan titik henti: <code>col-12 col-md-6 col-lg-4</code> berarti penuh di ponsel, setengah mulai 768px, sepertiga mulai 992px.", "Titik henti Bootstrap: <code>sm</code> 576px, <code>md</code> 768px, <code>lg</code> 992px, <code>xl</code> 1200px, <code>xxl</code> 1400px. Jarak antarkolom diatur dengan <code>g-3</code> (gutter)."], "html": "<div class=\"container py-3\">\n  <div class=\"row g-3\">\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Dart</div></div>\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Kotlin</div></div>\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Flutter</div></div>\n    <div class=\"col-12 col-md-6\"><div class=\"p-3 bg-info-subtle border rounded\">Compose</div></div>\n  </div>\n</div>", "bs": true, "task": {"q": "Buat setiap kolom menjadi sepertiga lebar di layar besar: tambahkan <code>col-lg-4</code> pada keempat kolom.", "test": "[...document.querySelectorAll('.row > div')].every(d=>d.classList.contains('col-lg-4'))", "hint": "Tambahkan col-lg-4 setelah col-md-6 di setiap div kolom."}, "pts": ["container → row → col.", "12 kolom per baris; col-md-6 = setengah mulai md.", "Gutter: g-0 sampai g-5."], "q": [["Berapa lebar col-3 dalam baris 12 kolom?", ["Seperempat", "Sepertiga", "Setengah"], 0, "3/12 = 1/4."], ["Titik henti lg di Bootstrap 5 mulai lebar?", ["768px", "992px", "1200px"], 1, "sm 576, md 768, lg 992, xl 1200, xxl 1400."]], "so": [{"q": "Buat tata letak sidebar 3 kolom dan konten 9 kolom mulai md, ditumpuk di ponsel.", "h": "row lalu col-md-3 dan col-md-9.", "a": "<div class=\"container\">\n  <div class=\"row g-3\">\n    <aside class=\"col-md-3\"><div class=\"p-3 bg-light border\">Menu</div></aside>\n    <main class=\"col-md-9\"><div class=\"p-3 border\">Konten</div></main>\n  </div>\n</div>", "lang": "html"}, {"q": "Buat satu kolom selebar 6 yang berada di tengah baris.", "h": "offset-3 menggeser kolom 3 satuan, atau justify-content-center pada row.", "a": "<div class=\"row justify-content-center\">\n  <div class=\"col-6\"><div class=\"p-3 border text-center\">Tengah</div></div>\n</div>", "lang": "html"}]}, {"k": "w", "t": "Utilitas, tipografi, dan warna", "nodes": [], "b": ["Bootstrap juga punya kelas utilitas: jarak <code>m-3</code>, <code>p-2</code>, <code>mt-4</code>, <code>px-5</code> (skala 0–5), tampilan <code>d-flex</code>, <code>d-none d-md-block</code>, perataan <code>justify-content-between</code>, <code>align-items-center</code>, <code>text-center</code>.", "Warna tema: <code>primary</code>, <code>secondary</code>, <code>success</code>, <code>danger</code>, <code>warning</code>, <code>info</code>, <code>light</code>, <code>dark</code>. Dipakai sebagai <code>text-danger</code>, <code>bg-warning</code>, <code>border-success</code>.", "Tipografi: <code>display-1</code> sampai <code>display-6</code> untuk judul besar, <code>lead</code> untuk paragraf pembuka, <code>fw-bold</code>, <code>fs-5</code>, <code>text-muted</code>/<code>text-body-secondary</code>."], "html": "<div class=\"container py-3\">\n  <div class=\"d-flex justify-content-between align-items-center p-3 bg-light border rounded\">\n    <span class=\"fw-bold\">Pesanan #1024</span>\n    <span id=\"status\" class=\"badge bg-secondary\">Diproses</span>\n  </div>\n  <p class=\"mt-3 text-body-secondary\">Estimasi tiba: 2 hari.</p>\n</div>", "bs": true, "task": {"q": "Ubah status menjadi hijau dengan <code>bg-success</code> menggantikan <code>bg-secondary</code>.", "test": "document.getElementById('status').classList.contains('bg-success')", "hint": "Ganti bg-secondary pada span#status."}, "pts": ["Jarak: m-/p- + arah + skala 0–5.", "d-flex, justify-content-*, align-items-*.", "Warna tema: primary, success, danger, warning, info, dll."], "q": [["Kelas mana yang menyembunyikan elemen di ponsel tapi menampilkannya mulai md?", ["d-none d-md-block", "d-md-none d-block", "hide-md"], 0, "d-none untuk semua, lalu d-md-block mulai md."]], "so": [{"q": "Buat bilah ringkasan: teks kiri \"Total belanja\", angka kanan tebal berwarna hijau, sejajar vertikal, padding 3, garis tepi, sudut membulat.", "h": "d-flex justify-content-between align-items-center p-3 border rounded; fw-bold text-success.", "a": "<div class=\"d-flex justify-content-between align-items-center p-3 border rounded\">\n  <span>Total belanja</span>\n  <span class=\"fw-bold text-success fs-5\">Rp66.150</span>\n</div>", "lang": "html"}, {"q": "Sembunyikan kolom keterangan di ponsel dan tampilkan mulai lg.", "h": "d-none d-lg-block.", "a": "<p class=\"d-none d-lg-block text-body-secondary\">Keterangan tambahan untuk layar lebar.</p>", "lang": "html"}]}]}, {"t": "Komponen Bootstrap", "lvl": "Menengah", "d": "Tombol, kartu, alert, badge, navbar, form dengan validasi, dan modal.", "nodes": ["Buttons", "Cards", "Alerts", "Navbar", "Forms", "Validation", "Modal"], "lessons": [{"k": "w", "t": "Tombol, kartu, alert, dan badge", "nodes": [], "b": ["Tombol: <code>btn btn-primary</code>, versi garis tepi <code>btn-outline-primary</code>, ukuran <code>btn-sm</code>/<code>btn-lg</code>.", "Kartu: <code>.card</code> berisi <code>.card-img-top</code>, <code>.card-body</code>, <code>.card-title</code>, <code>.card-text</code>.", "Alert untuk pesan: <code>alert alert-warning</code>. Badge untuk label kecil: <code>badge text-bg-danger</code>."], "html": "<div class=\"container py-3\">\n  <div class=\"alert alert-warning\">Stok kopi Gayo tinggal sedikit.</div>\n  <div class=\"card\" style=\"max-width:18rem\">\n    <div class=\"card-body\">\n      <h5 class=\"card-title\">Kopi Gayo <span class=\"badge text-bg-danger\">Baru</span></h5>\n      <p class=\"card-text\">Arabika dari Aceh, 250 gram.</p>\n      <a class=\"btn btn-primary\">Rp 85.000</a>\n    </div>\n  </div>\n</div>", "bs": true, "task": {"q": "Tambahkan tombol kedua di dalam kartu dengan kelas <code>btn btn-outline-secondary</code>.", "test": "!!document.querySelector('.card .btn.btn-outline-secondary')", "hint": "Tulis <a class=\"btn btn-outline-secondary\">Detail</a> setelah tombol pertama."}, "pts": ["btn + btn-{warna} atau btn-outline-{warna}.", "card → card-body → card-title/card-text.", "alert alert-{warna}; badge text-bg-{warna}."], "q": [["Kelas apa untuk tombol bergaris tepi merah?", ["btn btn-outline-danger", "btn btn-danger-outline", "btn-border-red"], 0, "Pola btn-outline-{warna}."], ["Atribut untuk tombol penutup alert?", ["data-bs-dismiss=\"alert\"", "data-close", "onclick=\"hide()\""], 0, "Sama polanya dengan modal."]], "so": [{"q": "Buat alert sukses yang bisa ditutup dengan tombol silang.", "h": "alert alert-success alert-dismissible fade show + button.btn-close data-bs-dismiss=\"alert\".", "a": "<div class=\"alert alert-success alert-dismissible fade show\" role=\"alert\">\n  Pesanan berhasil dibuat.\n  <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"Tutup\"></button>\n</div>", "lang": "html"}, {"q": "Buat tiga kartu produk sama tinggi berdampingan mulai md.", "h": "row row-cols-1 row-cols-md-3 g-3 dan card h-100.", "a": "<div class=\"row row-cols-1 row-cols-md-3 g-3\">\n  <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kopi Gayo</h5><p class=\"card-text\">Rp85.000</p></div></div></div>\n  <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kopi Toraja</h5><p class=\"card-text\">Rp90.000</p></div></div></div>\n  <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kopi Kintamani</h5><p class=\"card-text\">Rp80.000</p></div></div></div>\n</div>", "lang": "html"}]}, {"k": "w", "t": "Navbar yang bisa dilipat", "nodes": [], "b": ["Navbar Bootstrap otomatis berubah menjadi menu hamburger di layar kecil. Kuncinya: <code>navbar-expand-lg</code> (melebar mulai lg), tombol <code>navbar-toggler</code>, dan wadah <code>collapse navbar-collapse</code>.", "Tombol pembuka memakai atribut <code>data-bs-toggle=\"collapse\"</code> dan <code>data-bs-target=\"#menu\"</code>. Tidak perlu menulis JavaScript sendiri, bundle Bootstrap yang menanganinya.", "Pratinjau ini sempit, jadi kamu akan melihat tombol hamburger. Klik untuk membuka menu."], "html": "<nav class=\"navbar navbar-expand-lg bg-dark\" data-bs-theme=\"dark\">\n  <div class=\"container-fluid\">\n    <a class=\"navbar-brand\" href=\"#\">RuangKode</a>\n    <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#menu\" aria-controls=\"menu\" aria-expanded=\"false\" aria-label=\"Buka menu\">\n      <span class=\"navbar-toggler-icon\"></span>\n    </button>\n    <div class=\"collapse navbar-collapse\" id=\"menu\">\n      <ul class=\"navbar-nav\">\n        <li class=\"nav-item\"><a class=\"nav-link active\" href=\"#\">Beranda</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"#\">Kursus</a></li>\n      </ul>\n    </div>\n  </div>\n</nav>", "bs": true, "task": {"q": "Tambahkan item menu ketiga \"Masuk\" di dalam <code>.navbar-nav</code>.", "test": "document.querySelectorAll('.navbar-nav .nav-item').length>=3", "hint": "Salin satu <li class=\"nav-item\">...</li> dan ganti teksnya."}, "pts": ["navbar-expand-{bp} menentukan kapan menu melebar.", "data-bs-toggle=\"collapse\" + data-bs-target=\"#id\"."], "q": [["Atribut apa yang menghubungkan tombol ke menu yang dilipat?", ["data-bs-target", "data-target-menu", "href saja"], 0, "data-bs-target berisi selector elemen collapse."]], "so": [{"q": "Ubah navbar agar melebar mulai md (bukan lg) dan menu rata kanan.", "h": "navbar-expand-md; tambahkan ms-auto pada ul.navbar-nav.", "a": "<nav class=\"navbar navbar-expand-md bg-body-tertiary\">\n  <div class=\"container-fluid\">\n    <a class=\"navbar-brand\" href=\"#\">RuangKode</a>\n    <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#menu\" aria-controls=\"menu\" aria-expanded=\"false\" aria-label=\"Buka menu\"><span class=\"navbar-toggler-icon\"></span></button>\n    <div class=\"collapse navbar-collapse\" id=\"menu\">\n      <ul class=\"navbar-nav ms-auto\">\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"#\">Beranda</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link\" href=\"#\">Kursus</a></li>\n      </ul>\n    </div>\n  </div>\n</nav>", "lang": "html"}]}, {"k": "w", "t": "Form dan validasi", "nodes": [], "b": ["Input memakai <code>form-control</code>, pilihan <code>form-select</code>, kotak centang <code>form-check-input</code>, label <code>form-label</code>.", "Validasi bawaan: beri form atribut <code>novalidate</code> dan kelas <code>needs-validation</code>. Saat dikirim, tambahkan kelas <code>was-validated</code> agar Bootstrap menampilkan <code>.invalid-feedback</code> di bawah input yang salah.", "Kamu juga bisa menandai satu input secara manual dengan <code>is-invalid</code> atau <code>is-valid</code>."], "html": "<form id=\"daftar\" class=\"container py-3 needs-validation\" novalidate>\n  <div class=\"mb-3\">\n    <label for=\"nama\" class=\"form-label\">Nama</label>\n    <input id=\"nama\" class=\"form-control\" required>\n    <div class=\"invalid-feedback\">Nama wajib diisi.</div>\n  </div>\n  <div class=\"mb-3\">\n    <label for=\"kelas\" class=\"form-label\">Kelas</label>\n    <select id=\"kelas\" class=\"form-select\"><option>Flutter</option><option>Compose</option></select>\n  </div>\n  <button class=\"btn btn-primary\">Daftar</button>\n</form>", "js": "const f = document.getElementById('daftar');\nf.addEventListener('submit', e => {\n  e.preventDefault();\n  // tandai form agar Bootstrap menampilkan pesan validasi\n  f.classList.add('was-validated');\n  if (f.checkValidity()) console.log('Terkirim:', f.nama.value);\n});", "bs": true, "task": {"q": "Tambahkan input email (<code>type=\"email\"</code>, kelas <code>form-control</code>, <code>required</code>) beserta pesan <code>invalid-feedback</code>.", "test": "(e=>!!e&&e.required&&e.classList.contains('form-control')&&!!e.parentElement.querySelector('.invalid-feedback'))(document.querySelector('#daftar input[type=email]'))", "hint": "Salin blok div.mb-3 untuk Nama, ganti id, label, dan type menjadi email."}, "pts": ["form-control, form-select, form-check-input, form-label.", "novalidate + was-validated menampilkan invalid-feedback."], "q": [["Kelas apa yang membuat Bootstrap menampilkan pesan validasi untuk seluruh form?", ["was-validated", "is-validated", "validate-all"], 0, "was-validated dipasang pada form."], ["Kelas untuk menandai satu input tidak valid secara manual?", ["is-invalid", "invalid", "has-error"], 0, "is-valid untuk yang benar."]], "so": [{"q": "Buat dua field berdampingan (Nama depan, Nama belakang) mulai md memakai grid di dalam form.", "h": "div.row.g-3 lalu col-md-6 untuk setiap field.", "a": "<form class=\"row g-3\">\n  <div class=\"col-md-6\"><label class=\"form-label\" for=\"dp\">Nama depan</label><input id=\"dp\" class=\"form-control\"></div>\n  <div class=\"col-md-6\"><label class=\"form-label\" for=\"bl\">Nama belakang</label><input id=\"bl\" class=\"form-control\"></div>\n</form>", "lang": "html"}, {"q": "Buat kotak centang persetujuan yang wajib dicentang, terpisah dari kotak centang langganan berita.", "h": "form-check + form-check-input + form-check-label; required hanya pada persetujuan.", "a": "<div class=\"form-check\">\n  <input class=\"form-check-input\" type=\"checkbox\" id=\"setuju\" required>\n  <label class=\"form-check-label\" for=\"setuju\">Saya menyetujui pemrosesan data untuk pendaftaran</label>\n  <div class=\"invalid-feedback\">Centang untuk melanjutkan.</div>\n</div>\n<div class=\"form-check\">\n  <input class=\"form-check-input\" type=\"checkbox\" id=\"berita\">\n  <label class=\"form-check-label\" for=\"berita\">Kirimi saya info kelas baru (opsional)</label>\n</div>", "lang": "html"}]}, {"k": "w", "t": "Modal dan komponen JavaScript", "nodes": [], "b": ["Modal adalah kotak dialog. Strukturnya <code>.modal</code> → <code>.modal-dialog</code> → <code>.modal-content</code> → header, body, footer.", "Membukanya cukup dengan tombol berisi <code>data-bs-toggle=\"modal\"</code> dan <code>data-bs-target=\"#idModal\"</code>. Tombol tutup memakai <code>data-bs-dismiss=\"modal\"</code>.", "Komponen lain yang memakai pola sama: dropdown (<code>data-bs-toggle=\"dropdown\"</code>), tooltip, offcanvas, accordion, dan toast. Bisa juga dibuka lewat JS: <code>new bootstrap.Modal(el).show()</code>."], "html": "<div class=\"container py-3\">\n  <button class=\"btn btn-danger\" data-bs-toggle=\"modal\" data-bs-target=\"#konfirmasi\">Hapus akun</button>\n</div>\n<div class=\"modal fade\" id=\"konfirmasi\" tabindex=\"-1\" aria-labelledby=\"judulModal\" aria-hidden=\"true\">\n  <div class=\"modal-dialog\">\n    <div class=\"modal-content\">\n      <div class=\"modal-header\"><h5 class=\"modal-title\" id=\"judulModal\">Yakin?</h5>\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Tutup\"></button></div>\n      <div class=\"modal-body\">Akun yang dihapus tidak bisa dipulihkan.</div>\n      <div class=\"modal-footer\">\n        <button class=\"btn btn-danger\">Ya, hapus</button>\n      </div>\n    </div>\n  </div>\n</div>", "bs": true, "task": {"q": "Tambahkan tombol \"Batal\" di footer modal yang menutup modal (<code>data-bs-dismiss=\"modal\"</code>).", "test": "!!document.querySelector('.modal-footer [data-bs-dismiss=\"modal\"]')", "hint": "Tulis <button class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Batal</button> di .modal-footer."}, "pts": ["data-bs-toggle=\"modal\" + data-bs-target membuka modal.", "data-bs-dismiss=\"modal\" menutupnya.", "Bisa juga lewat new bootstrap.Modal(el)."], "q": [["Atribut apa untuk tombol yang menutup modal?", ["data-bs-dismiss=\"modal\"", "data-bs-close", "onclick=\"close()\""], 0, "data-bs-dismiss menutup komponen induknya."]], "so": [{"q": "Buka modal lewat JavaScript, bukan atribut data, saat halaman selesai dimuat.", "h": "new bootstrap.Modal(elemen).show().", "a": "<script>\n  const m = new bootstrap.Modal(document.getElementById('konfirmasi'));\n  m.show();\n</script>", "lang": "html"}, {"q": "Buat modal yang berada di tengah layar dan tidak tertutup saat area luar diklik.", "h": "modal-dialog-centered; data-bs-backdrop=\"static\" pada .modal.", "a": "<div class=\"modal fade\" id=\"info\" data-bs-backdrop=\"static\" tabindex=\"-1\" aria-hidden=\"true\">\n  <div class=\"modal-dialog modal-dialog-centered\">\n    <div class=\"modal-content\">\n      <div class=\"modal-body\">Pembayaran sedang diproses.</div>\n      <div class=\"modal-footer\"><button class=\"btn btn-primary\" data-bs-dismiss=\"modal\">Mengerti</button></div>\n    </div>\n  </div>\n</div>", "lang": "html"}]}]}, {"t": "Kustomisasi dan proyek", "lvl": "Menengah", "d": "Mengubah tema lewat variabel CSS dan Sass, mode gelap, lalu membuat halaman lengkap.", "nodes": ["CSS Variables", "Sass", "Color Modes", "Project"], "lessons": [{"k": "w", "t": "Variabel CSS, Sass, dan mode gelap", "nodes": [], "b": ["Bootstrap 5.3 menyimpan warna dan ukuran di <b>variabel CSS</b> berawalan <code>--bs-</code>. Kamu bisa menimpanya: <code>:root { --bs-primary: #B4532A; --bs-primary-rgb: 180,83,42; }</code>. Untuk tombol, ubah variabel komponennya, misalnya <code>.btn-primary { --bs-btn-bg: #B4532A; }</code>.", "Untuk kustomisasi menyeluruh, pakai <b>Sass</b>: <code>npm install bootstrap sass</code>, lalu di <code>main.scss</code> tulis <code>$primary: #B4532A;</code> sebelum <code>@import \"bootstrap/scss/bootstrap\";</code>. Semua komponen ikut berubah.", "Mode gelap: tambahkan <code>data-bs-theme=\"dark\"</code> pada <code>&lt;html&gt;</code> atau pada satu elemen saja."], "html": "<div class=\"container py-3\">\n  <button id=\"utama\" class=\"btn btn-primary\">Tombol utama</button>\n  <div id=\"kotak\" class=\"card mt-3\"><div class=\"card-body\">Kartu ini bisa dibuat gelap.</div></div>\n</div>", "css": ".btn-primary {\n  --bs-btn-bg: #B4532A;\n  --bs-btn-border-color: #B4532A;\n  --bs-btn-hover-bg: #8F3F1F;\n}", "bs": true, "task": {"q": "Buat kartu tampil gelap dengan menambahkan atribut <code>data-bs-theme=\"dark\"</code> pada <code>#kotak</code>.", "test": "document.getElementById('kotak').getAttribute('data-bs-theme')==='dark'", "hint": "Tulis data-bs-theme=\"dark\" di tag div#kotak."}, "pts": ["Variabel --bs-* bisa ditimpa di CSS.", "Sass: ubah $primary dll. sebelum import Bootstrap.", "data-bs-theme=\"dark\" untuk mode gelap."], "q": [["Cara paling menyeluruh mengganti warna primer Bootstrap?", ["Mengubah $primary di Sass sebelum import", "Menambah !important di setiap tombol", "Mengedit bootstrap.min.css"], 0, "Sass membangun ulang semua komponen dengan nilai baru."]], "so": [{"q": "Ubah sudut membulat semua komponen menjadi lebih besar lewat variabel CSS.", "h": "Timpa --bs-border-radius (dan variannya) di :root.", "a": "<style>\n  :root {\n    --bs-border-radius: .75rem;\n    --bs-border-radius-lg: 1rem;\n    --bs-border-radius-sm: .5rem;\n  }\n</style>", "lang": "html"}, {"q": "Tulis file Sass yang mengganti warna primer menjadi #B4532A dan font dasar menjadi Inter.", "h": "Variabel Sass ditulis sebelum @import bootstrap.", "a": "// main.scss\n$primary: #B4532A;\n$font-family-base: \"Inter\", system-ui, sans-serif;\n\n@import \"bootstrap/scss/bootstrap\";", "lang": "html"}]}, {"k": "w", "t": "Proyek: halaman kursus", "nodes": [], "b": ["Gabungkan navbar, hero, grid kartu yang responsif, dan footer.", "Perhatikan grid: <code>row-cols-1 row-cols-md-3</code> adalah cara singkat membuat semua kolom anak sama lebar.", "Tantangan: tambahkan kartu kursus keempat dan ubah grid menjadi empat kolom di layar <code>lg</code> dengan <code>row-cols-lg-4</code>."], "html": "<nav class=\"navbar bg-body-tertiary border-bottom\"><div class=\"container\"><span class=\"navbar-brand fw-bold\">RuangKode</span><a class=\"btn btn-sm btn-primary\">Daftar</a></div></nav>\n<header class=\"container py-5 text-center\">\n  <h1 class=\"display-5 fw-bold\">Jadi developer mobile</h1>\n  <p class=\"lead text-body-secondary\">Belajar Dart, Flutter, Kotlin, dan Compose dari nol.</p>\n</header>\n<section class=\"container pb-5\">\n  <div id=\"kursus\" class=\"row row-cols-1 row-cols-md-3 g-3\">\n    <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Dart</h5><p class=\"card-text\">Bahasa di balik Flutter.</p></div></div></div>\n    <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Flutter</h5><p class=\"card-text\">Satu kode untuk Android dan iOS.</p></div></div></div>\n    <div class=\"col\"><div class=\"card h-100\"><div class=\"card-body\"><h5 class=\"card-title\">Kotlin</h5><p class=\"card-text\">Bahasa resmi Android.</p></div></div></div>\n  </div>\n</section>\n<footer class=\"border-top py-3 text-center small text-body-secondary\">© 2026 RuangKode</footer>", "bs": true, "task": {"q": "Tambahkan kartu keempat di <code>#kursus</code> dan kelas <code>row-cols-lg-4</code>.", "test": "(g=>g.children.length>=4&&g.classList.contains('row-cols-lg-4'))(document.getElementById('kursus'))", "hint": "Salin satu div.col, ubah judulnya, lalu tambahkan row-cols-lg-4 pada div#kursus."}, "pts": ["row-cols-* menyamakan lebar semua kolom anak.", "card h-100 membuat tinggi kartu seragam."], "q": [["Tailwind dan Bootstrap, mana yang menyediakan komponen siap pakai seperti modal?", ["Bootstrap", "Tailwind", "Keduanya sama persis"], 0, "Tailwind fokus pada utilitas; Bootstrap menyertakan komponen dan JS-nya."]], "so": [{"q": "Tambahkan bagian FAQ memakai accordion Bootstrap dengan dua pertanyaan.", "h": "accordion > accordion-item > accordion-header (button) + accordion-collapse.", "a": "<div class=\"accordion container mb-5\" id=\"faq\">\n  <div class=\"accordion-item\">\n    <h2 class=\"accordion-header\"><button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#q1\">Apakah gratis?</button></h2>\n    <div id=\"q1\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#faq\"><div class=\"accordion-body\">Ya, semua materi gratis.</div></div>\n  </div>\n  <div class=\"accordion-item\">\n    <h2 class=\"accordion-header\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#q2\">Perlu instal sesuatu?</button></h2>\n    <div id=\"q2\" class=\"accordion-collapse collapse\" data-bs-parent=\"#faq\"><div class=\"accordion-body\">Cukup browser untuk sebagian besar latihan.</div></div>\n  </div>\n</div>", "lang": "html"}]}]}, {"t": "Komponen lanjutan Bootstrap", "lvl": "Menengah", "d": "Dropdown, tab, accordion, offcanvas, toast, tooltip, tabel, list group, dan pagination.", "nodes": ["Dropdown", "Tabs", "Offcanvas", "Toast", "Tables"], "lessons": [{"k": "w", "t": "Dropdown, tab, dan accordion", "nodes": [], "b": ["<b>Dropdown</b>: tombol dengan <code>data-bs-toggle=\"dropdown\"</code> dan daftar <code>.dropdown-menu</code> berisi <code>.dropdown-item</code>.", "<b>Tab</b>: <code>.nav.nav-tabs</code> berisi tombol <code>data-bs-toggle=\"tab\"</code> yang menunjuk ke <code>.tab-pane</code> di dalam <code>.tab-content</code>.", "<b>Accordion</b>: daftar bagian yang bisa dilipat. Tambahkan <code>data-bs-parent</code> agar hanya satu bagian terbuka dalam satu waktu. Semua ini berjalan tanpa JavaScript tambahan."], "html": "<div class=\"container py-3\">\n  <div class=\"dropdown mb-3\">\n    <button class=\"btn btn-secondary dropdown-toggle\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">Urutkan</button>\n    <ul class=\"dropdown-menu\">\n      <li><a class=\"dropdown-item\" href=\"#\">Termurah</a></li>\n      <li><a class=\"dropdown-item\" href=\"#\">Terbaru</a></li>\n    </ul>\n  </div>\n  <ul class=\"nav nav-tabs\" role=\"tablist\">\n    <li class=\"nav-item\"><button class=\"nav-link active\" data-bs-toggle=\"tab\" data-bs-target=\"#deskripsi\" type=\"button\" role=\"tab\">Deskripsi</button></li>\n    <li class=\"nav-item\"><button class=\"nav-link\" data-bs-toggle=\"tab\" data-bs-target=\"#ulasan\" type=\"button\" role=\"tab\">Ulasan</button></li>\n  </ul>\n  <div id=\"isiTab\" class=\"tab-content border border-top-0 p-3\">\n    <div class=\"tab-pane fade show active\" id=\"deskripsi\" role=\"tabpanel\">Kopi arabika 250 gram.</div>\n    <div class=\"tab-pane fade\" id=\"ulasan\" role=\"tabpanel\">★★★★★ Enak sekali.</div>\n  </div>\n</div>", "bs": true, "task": {"q": "Tambahkan tab ketiga \"Pengiriman\" lengkap dengan tab-pane berisi teksnya.", "test": "document.querySelectorAll('.nav-tabs .nav-link').length>=3&&document.querySelectorAll('#isiTab .tab-pane').length>=3", "hint": "Salin satu li.nav-item dan satu div.tab-pane, beri id baru, dan samakan data-bs-target dengan id itu."}, "pts": ["dropdown: data-bs-toggle=\"dropdown\".", "tab: data-bs-toggle=\"tab\" + tab-pane.", "accordion: data-bs-parent agar satu terbuka."], "q": [["Atribut accordion agar hanya satu bagian terbuka?", ["data-bs-parent", "data-single", "aria-expanded"], 0, "Menunjuk ke wadah accordion."]]}, {"k": "w", "t": "Offcanvas, toast, dan tooltip", "nodes": [], "b": ["<b>Offcanvas</b> adalah panel yang meluncur dari tepi layar, cocok untuk menu samping atau filter di ponsel. Dibuka dengan <code>data-bs-toggle=\"offcanvas\"</code>.", "<b>Toast</b> adalah notifikasi kecil yang muncul lalu hilang. Toast dan <b>tooltip</b> perlu diaktifkan dengan JavaScript: <code>new bootstrap.Toast(el).show()</code> dan <code>new bootstrap.Tooltip(el)</code>.", "Komponen yang perlu diaktifkan lewat JS ini disebut opt-in, karena demi performa Bootstrap tidak memasangnya otomatis."], "html": "<div class=\"container py-3 d-flex gap-2 flex-wrap\">\n  <button class=\"btn btn-outline-dark\" data-bs-toggle=\"offcanvas\" data-bs-target=\"#filter\">Filter</button>\n  <button id=\"btnToast\" class=\"btn btn-success\">Tambah ke keranjang</button>\n  <button id=\"info\" class=\"btn btn-outline-secondary\" data-bs-toggle=\"tooltip\" data-bs-title=\"Gratis ongkir di atas Rp100.000\">Info ongkir</button>\n</div>\n<div class=\"offcanvas offcanvas-start\" tabindex=\"-1\" id=\"filter\">\n  <div class=\"offcanvas-header\"><h5 class=\"offcanvas-title\">Filter</h5><button class=\"btn-close\" data-bs-dismiss=\"offcanvas\" aria-label=\"Tutup\"></button></div>\n  <div class=\"offcanvas-body\">Harga, kategori, rating...</div>\n</div>\n<div class=\"toast-container position-fixed bottom-0 end-0 p-3\">\n  <div id=\"notif\" class=\"toast\" role=\"status\" aria-live=\"polite\">\n    <div class=\"toast-body\">Produk ditambahkan ke keranjang.</div>\n  </div>\n</div>", "js": "document.getElementById('btnToast').addEventListener('click', () => {\n  new bootstrap.Toast(document.getElementById('notif')).show();\n});\n// aktifkan tooltip di sini", "bs": true, "task": {"q": "Aktifkan tooltip pada tombol <code>#info</code> dengan <code>new bootstrap.Tooltip(...)</code>, lalu tekan Jalankan dan Periksa.", "test": "!!(window.bootstrap&&bootstrap.Tooltip.getInstance(document.getElementById('info')))", "hint": "new bootstrap.Tooltip(document.getElementById('info'));"}, "pts": ["offcanvas untuk panel samping.", "Toast dan tooltip diaktifkan dengan JS.", "toast-container position-fixed untuk posisi."], "q": [["Komponen mana yang harus diaktifkan lewat JavaScript?", ["Tooltip", "Card", "Grid"], 0, "Tooltip dan popover bersifat opt-in."]]}, {"k": "w", "t": "Tabel, list group, dan pagination", "nodes": [], "b": ["Tabel: <code>.table</code> lalu tambahan <code>.table-striped</code> (belang), <code>.table-hover</code>, <code>.table-sm</code>. Bungkus dengan <code>.table-responsive</code> agar tabel lebar bisa digulir di ponsel tanpa merusak halaman.", "<b>List group</b> (<code>.list-group</code> dan <code>.list-group-item</code>) cocok untuk daftar pengaturan atau riwayat, dan bisa dipadukan dengan badge.", "<b>Pagination</b> (<code>.pagination</code>, <code>.page-item</code>, <code>.page-link</code>) untuk berpindah halaman data. Tandai halaman aktif dengan <code>.active</code> dan <code>aria-current=\"page\"</code>."], "html": "<div class=\"container py-3\">\n  <div class=\"table-responsive\">\n    <table id=\"tabel\" class=\"table\">\n      <thead><tr><th>Produk</th><th class=\"text-end\">Harga</th><th class=\"text-end\">Stok</th></tr></thead>\n      <tbody>\n        <tr><td>Kopi Gayo</td><td class=\"text-end\">85.000</td><td class=\"text-end\">12</td></tr>\n        <tr><td>Kopi Toraja</td><td class=\"text-end\">90.000</td><td class=\"text-end\">4</td></tr>\n        <tr><td>Kopi Kintamani</td><td class=\"text-end\">80.000</td><td class=\"text-end\">0</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <nav aria-label=\"Halaman produk\">\n    <ul class=\"pagination\">\n      <li class=\"page-item\"><a class=\"page-link\" href=\"#\">1</a></li>\n      <li class=\"page-item\"><a class=\"page-link\" href=\"#\">2</a></li>\n      <li class=\"page-item\"><a class=\"page-link\" href=\"#\">3</a></li>\n    </ul>\n  </nav>\n</div>", "bs": true, "task": {"q": "Beri tabel kelas <code>table-striped</code> dan <code>table-hover</code>, lalu tandai halaman 1 sebagai aktif (<code>active</code> pada li pertama).", "test": "(t=>t.classList.contains('table-striped')&&t.classList.contains('table-hover'))(document.getElementById('tabel'))&&document.querySelector('.pagination .page-item').classList.contains('active')", "hint": "Tambahkan dua kelas pada table#tabel dan active pada li.page-item pertama."}, "pts": ["table + table-striped/hover, bungkus table-responsive.", "list-group untuk daftar.", "pagination dengan active dan aria-current."], "q": [["Kenapa tabel dibungkus .table-responsive?", ["Agar bisa digulir horizontal di layar sempit", "Agar berwarna", "Agar bisa diurutkan"], 0, "Halaman tidak ikut melebar."]]}, {"k": "w", "t": "Utilitas lanjutan: stack, posisi, dan rasio", "nodes": [], "b": ["<code>.hstack</code> dan <code>.vstack</code> adalah jalan pintas flexbox dengan <code>gap-*</code>. <code>.ms-auto</code> mendorong elemen ke kanan.", "Posisi: <code>position-relative</code>, <code>position-absolute</code>, <code>top-0 start-100 translate-middle</code> untuk badge notifikasi di pojok tombol.", "Rasio: <code>.ratio .ratio-16x9</code> menjaga video atau gambar tetap proporsional. <code>object-fit-cover</code> memotong gambar agar penuh tanpa gepeng."], "html": "<div class=\"container py-3\">\n  <div class=\"hstack gap-3 p-3 border rounded\">\n    <b>Keranjang</b>\n    <button id=\"lonceng\" class=\"btn btn-primary ms-auto\">\n      Notifikasi\n    </button>\n  </div>\n  <div class=\"ratio ratio-16x9 mt-3 bg-secondary-subtle rounded\"><div class=\"d-flex align-items-center justify-content-center\">Area video 16:9</div></div>\n</div>", "bs": true, "task": {"q": "Tambahkan badge merah angka 3 di pojok kanan atas tombol: tombol diberi <code>position-relative</code>, badge diberi <code>position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger</code>.", "test": "(b=>b.classList.contains('position-relative')&&!!b.querySelector('.badge.position-absolute.bg-danger'))(document.getElementById('lonceng'))", "hint": "<span class=\"position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger\">3</span> di dalam tombol."}, "pts": ["hstack/vstack + gap.", "position-* + translate-middle untuk badge pojok.", "ratio-16x9 untuk proporsi tetap."], "q": [["Kelas yang mendorong elemen ke kanan di dalam flex?", ["ms-auto", "float-end", "text-end"], 0, "margin-start auto memakan ruang kosong."]]}]}];
